/* global globalThis */
// Adapted from the approved SynScore v24 engine; immutable round membership.
const FRUIT_IDS = [
  "banana",
  "guava",
  "wax-apple",
  "strawberry",
  "lemon",
  "starfruit",
  "cherry",
  "lychee",
  "grape",
  "pineapple",
  "peach",
  "persimmon",
  "pear",
  "orange",
  "jujube",
  "mango",
  "apple",
  "tomato",
  "durian",
  "watermelon",
  "papaya",
  "cantaloupe",
  "kiwi",
  "dragon-fruit",
];
const initial = () => ({
  selected: [
    "banana",
    "guava",
    "strawberry",
    "grape",
    "pineapple",
    "peach",
    "apple",
    "watermelon",
  ],
  mode: "full",
  seven: "rest",
  restSeen: [],
  rounds: [],
});
const activeRound = (s) => s.rounds.findLast((r) => r.status === "active");
function shuffle(a, rng = Math.random) {
  const b = [...a];
  for (let i = b.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    [b[i], b[j]] = [b[j], b[i]];
  }
  return b;
}
function team(r, ref) {
  if (r.teams[ref]) return r.teams[ref];
  const m = /^([WL])(\d+)$/.exec(ref);
  if (!m) return null;
  const game = r.matches[Number(m[2])];
  if (!game?.score || game.status !== "done") return null;
  const winner = game.score[0] > game.score[1] ? game.a : game.b;
  const loser = game.score[0] > game.score[1] ? game.b : game.a;
  return team(r, m[1] === "W" ? winner : loser);
}
function createRound(s, rng = Math.random) {
  if (activeRound(s)) throw new Error("請先完成本輪，或結束本輪後再抽組。");
  validateRoster(s.selected);
  if (
    !["full", "quick"].includes(s.mode) ||
    !["rest", "borrow"].includes(s.seven)
  )
    throw new Error("賽制設定不正確。");
  const n = s.selected.length;
  if (n < 4 || n > 10)
    throw new Error("目前支援 4–10 人賽程；11 人以上的規則尚未設定。");
  const out = structuredClone(s);
  let players = [...s.selected],
    rest = null;
  const previousRest = [...s.restSeen];
  if (n === 5 || n === 9 || (n === 7 && s.seven === "rest")) {
    let eligible = players.filter((p) => !out.restSeen.includes(p));
    if (!eligible.length) {
      out.restSeen = [];
      eligible = players;
    }
    rest = shuffle(eligible, rng)[0];
    out.restSeen.push(rest);
    players = players.filter((p) => p !== rest);
  }
  const history = {};
  for (const old of s.rounds) {
    if (
      old.status === "aborted" &&
      !old.matches.some((m) => m.status === "done")
    )
      continue;
    const seen = new Set();
    for (const t of Object.values(old.teams)) {
      if (t.length === 2) {
        const key = [...t].sort().join("|");
        if (!seen.has(key)) {
          history[key] = (history[key] || 0) + 1;
          seen.add(key);
        }
      }
    }
  }
  let best = shuffle(players, rng),
    bestScore = Infinity;
  for (let k = 0; k < 240; k++) {
    const candidate = shuffle(players, rng);
    let cost = 0;
    for (let j = 0; j + 1 < candidate.length; j += 2) {
      const count =
        history[[candidate[j], candidate[j + 1]].sort().join("|")] || 0;
      cost += count ? 1000 + count * 20 : 0;
    }
    if (cost < bestScore) {
      best = candidate;
      bestScore = cost;
    }
    if (cost === 0) break;
  }
  const teams = {};
  for (let j = 0; j < best.length; j += 2)
    teams[String.fromCharCode(65 + j / 2)] = best.slice(j, j + 2);
  let fixtures;
  if (n === 7 && s.seven === "borrow")
    fixtures = [
      ["A", "B"],
      ["C", "補位隊"],
    ];
  else if (players.length === 4) fixtures = [["A", "B"]];
  else if (players.length === 6)
    fixtures = [
      ["A", "B"],
      ["C", "A"],
      ["B", "C"],
    ];
  else if (players.length === 8)
    fixtures =
      s.mode === "quick"
        ? [
            ["A", "B"],
            ["C", "D"],
          ]
        : [
            ["A", "B"],
            ["C", "D"],
            ["W0", "W1"],
            ["L0", "L1"],
          ];
  else
    fixtures = [
      ["A", "B"],
      ["C", "D"],
      ["E", "A"],
      ["B", "C"],
      ["D", "E"],
    ];
  const round = {
    id: globalThis.crypto.randomUUID(),
    roster: [...s.selected],
    teams,
    rest,
    previousRest,
    matches: fixtures.map(([a, b]) => ({ a, b, status: "pending" })),
    status: "active",
    mode: s.mode,
    seven: s.seven,
  };
  out.rounds.push(round);
  return out;
}
function chooseBorrow(s, fruit) {
  const out = structuredClone(s),
    r = activeRound(out);
  if (
    !r ||
    r.roster.length !== 7 ||
    r.seven !== "borrow" ||
    r.matches[1].status !== "pending"
  )
    throw new Error("目前不需要補位。");
  const winners = team(r, "W0");
  if (!winners?.includes(fruit)) throw new Error("請從首場勝隊選擇補位球員。");
  r.teams["補位隊"] = [r.teams.D[0], fruit];
  return out;
}
function recordMatch(s, index, a, b) {
  const out = structuredClone(s),
    r = activeRound(out);
  if (!r) throw new Error("沒有進行中的賽程。");
  if (r.matches.findIndex((m) => m.status === "pending") !== index)
    throw new Error("請依序完成本輪賽程。");
  const m = r.matches[index];
  if (!m || m.status !== "pending" || !team(r, m.a) || !team(r, m.b))
    throw new Error("本場對戰尚未確定。");
  if (
    !Number.isInteger(a) ||
    !Number.isInteger(b) ||
    a < 0 ||
    b < 0 ||
    a > 99 ||
    b > 99 ||
    a === b
  )
    throw new Error("請輸入 0–99 的整數比分，結束比賽時不得平手。");
  m.score = [a, b];
  m.status = "done";
  if (r.matches.every((x) => x.status === "done")) r.status = "complete";
  return out;
}
function abortRound(s) {
  const out = structuredClone(s),
    r = activeRound(out);
  if (!r) return out;
  r.status = "aborted";
  r.matches.forEach((m) => {
    if (m.status === "pending") m.status = "cancelled";
  });
  if (!r.matches.some((m) => m.status === "done"))
    out.restSeen = [...r.previousRest];
  return out;
}
function undoLastResult(s) {
  const out = structuredClone(s),
    r = out.rounds.at(-1);
  if (!r || r.status === "aborted")
    throw new Error("只能復原最近一輪的最後一場成績。");
  const i = r.matches.findLastIndex((m) => m.status === "done");
  if (i < 0) throw new Error("還沒有可復原的成績。");
  r.matches[i].status = "pending";
  delete r.matches[i].score;
  r.status = "active";
  if (r.seven === "borrow" && i === 0) delete r.teams["補位隊"];
  return out;
}
function stats(s) {
  const rows = {};
  for (const p of s.selected)
    rows[p] = { points: 0, wins: 0, losses: 0, games: 0 };
  for (const r of s.rounds) {
    for (const p of r.roster)
      rows[p] ??= { points: 0, wins: 0, losses: 0, games: 0 };
    for (const m of r.matches) {
      if (m.status !== "done" || !m.score) continue;
      const sides = [team(r, m.a), team(r, m.b)];
      sides.forEach((t, i) =>
        t.forEach((p) => {
          const z = rows[p];
          z.points += m.score[i];
          z.games++;
          if (m.score[i] > m.score[1 - i]) z.wins++;
          else z.losses++;
        }),
      );
    }
  }
  return rows;
}
function expectedGames(n, mode, seven) {
  if (n === 4 || n === 5) return 1;
  if (n === 6) return 3;
  if (n === 7) return seven === "borrow" ? 2 : 3;
  if (n === 8 || n === 9) return mode === "full" ? 4 : 2;
  if (n === 10) return 5;
  return 0;
}
/** Host integration only. Scores are bound to fruit identities, never red/blue screen sides. */
function applyHostResult(s, p) {
  if (
    !p ||
    typeof p.eventId !== "string" ||
    !p.eventId.trim() ||
    p.eventId.length > 160 ||
    typeof p.roomKey !== "string" ||
    !p.roomKey.trim() ||
    typeof p.matchId !== "string" ||
    typeof p.roundId !== "string" ||
    !Number.isInteger(p.matchIndex) ||
    !Array.isArray(p.teamA) ||
    !Array.isArray(p.teamB)
  )
    throw new Error("計分板賽果格式不正確。");
  if (!s.roomKey || p.roomKey !== s.roomKey || p.day !== s.day)
    throw new Error("房間或日期不符。");
  const target = s.targetPoints || 21,
    cap = target === 15 ? 21 : 30;
  const hi = Math.max(p.scoreA, p.scoreB),
    lo = Math.min(p.scoreA, p.scoreB);
  if (!(
    (hi === cap && lo >= cap - 2 && lo < cap) ||
    (hi >= target &&
      hi < cap &&
      ((hi === target && lo <= target - 2) || hi - lo === 2))
  ))
    throw new Error("比分尚未達到合法結束條件。");
  if (s.processedEvents?.includes(p.eventId)) return s;
  const r = activeRound(s);
  if (!r || r.id !== p.roundId) throw new Error("賽果所屬輪次與目前賽程不符。");
  if (p.matchId !== `${r.id}:${p.matchIndex}`)
    throw new Error("賽果比賽識別碼不符。");
  const m = r.matches[p.matchIndex];
  if (!m) throw new Error("賽果場次不存在。");
  const a = team(r, m.a),
    b = team(r, m.b);
  const same = (x, y) =>
    !!x &&
    x.length === y.length &&
    [...x].sort().join("|") === [...y].sort().join("|");
  let sa = p.scoreA,
    sb = p.scoreB;
  if (same(a, p.teamB) && same(b, p.teamA)) {
    sa = p.scoreB;
    sb = p.scoreA;
  } else if (!same(a, p.teamA) || !same(b, p.teamB))
    throw new Error("球員身份不符，未套用賽果。");
  const next = recordMatch(s, p.matchIndex, sa, sb);
  next.processedEvents = [...(s.processedEvents || []), p.eventId];
  return next;
}

function validateRoster(ids) {
  if (
    !Array.isArray(ids) ||
    ids.length > 24 ||
    ids.some((id) => !FRUIT_IDS.includes(id)) ||
    new Set(ids).size !== ids.length
  )
    throw new Error("水果名單必須使用不重複的有效水果。");
}

module.exports = {
  initial,
  activeRound,
  shuffle,
  team,
  createRound,
  chooseBorrow,
  recordMatch,
  abortRound,
  undoLastResult,
  stats,
  expectedGames,
  applyHostResult,
  validateRoster,
  FRUIT_IDS,
};
