import React from "react";
import "./voice.css";

const phases = {
  stopped: "已停止收音",
  starting: "正在啟動收音",
  listening: "正在聆聽",
  sending: "等待計分確認",
  restarting: "準備下一段收音",
  standby: "待命中（可計分時自動繼續）",
  error: "語音不可用",
};
export function VoiceStatus({ voice }) {
  if (!voice.enabled) return null;
  return (
    <aside className="voice-status" aria-label="語音計分狀態">
      <span>{phases[voice.status.phase]}</span>
      {voice.listening ? (
        <button onClick={voice.stop}>停止收音</button>
      ) : (
        <button onClick={voice.start} disabled={!voice.canStart}>
          開始收音
        </button>
      )}
      <output aria-live="polite">{voice.status.message}</output>
    </aside>
  );
}
export function VoiceSettings({ voice }) {
  return (
    <section className="voice-settings" aria-label="語音計分設定">
      <div className="settingrow">
        <b>語音計分（實驗性）</b>
        <button
          role="switch"
          aria-label="語音計分（實驗性）"
          aria-checked={voice.enabled}
          className={`ruleswitch ${voice.enabled ? "on" : ""}`}
          onClick={voice.toggle}
        >
          {voice.enabled ? "開" : "關"}
        </button>
      </div>
      <p>
        本機偏好，預設關閉。口令：紅方加一、藍方加一、加錯分數（撤回最後一分）。完賽後不接受語音撤回。
      </p>
      <p>
        換場、勝負確定、開啟設定或重新連線時會暫停，回到可計分狀態自動繼續；離開房間、背景化或按停止才需要手動重新開始。本程式不保存錄音、不自動上傳診斷；瀏覽器語音服務可能將音訊送往供應商雲端。
      </p>
      {!voice.supported && (
        <p role="status">
          此環境無法使用語音辨識；請使用支援的獨立瀏覽器與 HTTPS 或本機
          localhost。手動計分仍可使用。
        </p>
      )}
      <p role="status">
        {phases[voice.status.phase]}。{voice.status.message}
      </p>
      {voice.enabled && (
        <button
          className="secondary"
          onClick={voice.start}
          disabled={!voice.canStart}
        >
          開始收音
        </button>
      )}
      <details className="voice-diagnostics">
        <summary>語音診斷（{voice.logs.length} 筆）</summary>
        <p>
          只保留本次頁面最近 300
          筆文字紀錄，可能包含周遭對話。重新整理即清除；匯出前請留意內容。
        </p>
        <div className="actions">
          <button onClick={voice.exportLogs} disabled={!voice.logs.length}>
            匯出語音 LOG
          </button>
          <button onClick={voice.clearLogs} disabled={!voice.logs.length}>
            清除語音 LOG
          </button>
        </div>
        <pre aria-label="語音診斷紀錄">
          {voice.logs.map((row) => JSON.stringify(row)).join("\n") ||
            "尚無紀錄"}
        </pre>
      </details>
    </section>
  );
}
