// Presentation helpers for the current group-competition (fruit) match.
// Pure functions over the room state; no React, no room commands.
import * as engine from "./fruitEngine";

// Resolve a fixture reference (A, W0, L1, 補位隊) to the team key shown on the schedule.
export function teamKey(round, ref) {
  const m = /^([WL])(\d+)$/.exec(ref);
  if (!m) return ref;
  const game = round.matches[Number(m[2])];
  if (!game?.score || game.status !== "done") return null;
  const firstWon = game.score[0] > game.score[1];
  return teamKey(round, (m[1] === "W") === firstWon ? game.a : game.b);
}

function currentFixture(state) {
  if (state?.activityMode !== "fruit" || !state.currentMatch) return null;
  const round = state.fruit?.rounds.find(
    (r) => r.id === state.currentMatch.roundId,
  );
  const match = round?.matches[state.currentMatch.index];
  return match ? { round, match } : null;
}

// Label for the red (A) / blue (B) side: the schedule's team name in fruit mode,
// so "C 隊 vs A 隊" on the schedule never shows as "隊伍 A vs 隊伍 B".
export function sideLabel(state, side) {
  const fixture = currentFixture(state);
  const key =
    fixture &&
    teamKey(fixture.round, side === "A" ? fixture.match.a : fixture.match.b);
  if (!key) return `隊伍 ${side}`;
  return key === "補位隊" ? key : `${key} 隊`;
}

// Whether the pending match still needs its 7-player borrow chosen. Once the
// borrow is stored (even via a retried request) the picker must not offer it again.
export function borrowNeeded(pending) {
  if (!pending || pending.i < 0) return false;
  const m = pending.r.matches[pending.i];
  return !engine.team(pending.r, m.a) || !engine.team(pending.r, m.b);
}
