  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext("2d");
  ctx.fillStyle = "#f4f6f3";
  ctx.fillRect(0, 0, width, height);
  ctx.fillStyle = "#183b33";
  ctx.fillRect(0, 0, width, 180);
  const text = (str, x, y, size = 24, color = "#183b33") => {
    ctx.fillStyle = color;
    ctx.font = `600 ${size}px sans-serif`;
    ctx.fillText(str, x, y);
  };
  text("SynScore · 今日戰績", 42, 68, 42, "#fff");
  text(`${day || "全部日期"} · ${roomLabel}`, 44, 125, 25, "#d9e5da");
  let y = 230;
  for (const row of rows) {
    const image = new Image();
    await new Promise((resolve) => {
      image.onload = resolve;
      image.onerror = resolve;
      image.src = fruitURL(row.id);
    });
    if (image.naturalWidth) ctx.drawImage(image, 40, y - 35, 55, 55);
    text(`${name(row.id)}${day ? "" : " " + row.day}`, 115, y);
    text(
      `${row.points} 分    ${row.wins} 勝    ${row.losses} 敗    ${row.games} 場`,
      500,
      y,
    );
    y += 78;
  }
  for (const r of matches) {
    text(
      `${(r.teamA || []).map(name).join("＋") || "紅方"}   ${r.teamAScore} : ${r.teamBScore}   ${(r.teamB || []).map(name).join("＋") || "藍方"}`,
      45,
      y,
      23,
    );
    y += 68;
  }
