const { parseCommand } = require("./commands");

const ERROR_MESSAGES = {
  "not-allowed": "未取得收音權限，請檢查瀏覽器麥克風設定，再手動開始。",
  "service-not-allowed":
    "瀏覽器不允許語音服務。請用獨立 Safari 開啟；有 API 不代表服務可用。",
  "audio-capture": "無法取得麥克風，請確認收音裝置與其他 App 是否占用麥克風。",
  network: "語音服務連線失敗，請檢查網路後手動開始。",
  "language-not-supported": "語音服務不支援目前的繁體中文設定。",
};
// While the previous command is still being written, wait this long before giving up.
const BUSY_WAIT_MS = 5000,
  BUSY_POLL_MS = 250;
// Auto-resume only after the UI has settled, so transient renders (a dialog closing
// just before navigation) never flash the microphone on.
const WAKE_DELAY_MS = 300;

// This controller knows no scores, storage, room API or React state. The adapter
// supplies a live context and the existing room.act; nothing is queued here.
function createVoiceController({
  createRecognition,
  getContext,
  send,
  log,
  state,
  now = Date.now,
}) {
  // running: a recognizer session is live. armed: the user asked to listen and has not
  // stopped; a soft pause (match change, dialog, reconnect) keeps it armed so wake() resumes.
  let running = false,
    armed = false,
    busySince = null,
    epoch = 0,
    scope,
    recognizer = null,
    sending = false;
  let invalidateActive = null,
    wakeTimer = null;
  let rapidEmptyEnds = 0,
    segmentNumber = 0;
  const timers = new Set(),
    recent = new Map();
  const later = (fn, ms) => {
    const id = setTimeout(() => {
      timers.delete(id);
      fn();
    }, ms);
    timers.add(id);
    return id;
  };
  const cancel = (id) => {
    clearTimeout(id);
    timers.delete(id);
  };
  const report = (event, fields = {}) => log({ event, scope, ...fields });
  const eligible = (context) =>
    context.active && context.visible && context.inPlay;
  function teardown() {
    running = false;
    busySince = null;
    epoch++;
    for (const id of timers) clearTimeout(id);
    timers.clear();
    const old = recognizer;
    recognizer = null;
    invalidateActive = null;
    if (old) retire(old);
  }
  // Detach a recognizer from the session and make sure it gives the microphone back.
  // Safari can ignore abort() while the recognizer is still starting, so abort again if
  // it starts afterwards, and log when it really ends (visible in the exported LOG).
  function retire(rec) {
    const retiredScope = scope;
    const kill = () => {
      try {
        rec.abort();
      } catch (e) {
        log({ event: "abort-error", scope: retiredScope, detail: e.message });
      }
    };
    rec.onresult = rec.onspeechend = null;
    rec.onerror = () => {};
    rec.onstart = rec.onaudiostart = () => {
      log({ event: "late-start-aborted", scope: retiredScope });
      kill();
    };
    rec.onend = () => {
      rec.onstart = rec.onaudiostart = rec.onend = rec.onerror = null;
      log({ event: "mic-released", scope: retiredScope });
    };
    kill();
  }
  // Hard stop: needs another explicit user gesture (manual, disabled, background, errors).
  function stop(reason = "manual-stop") {
    armed = false;
    teardown();
    report("stopped", { reason });
    state({ phase: "stopped", reason });
  }
  // Soft pause: release the microphone but keep the user's intent; wake() resumes.
  function suspend(reason) {
    if (!running) return; // already paused or stopped
    armed = true;
    teardown();
    report("standby", { reason });
    state({
      phase: "standby",
      reason,
      message: "暫停收音，回到可計分狀態後會自動繼續。",
    });
  }
  function begin(context, event) {
    if (scope !== context.scope) recent.clear();
    scope = context.scope;
    running = true;
    epoch++;
    rapidEmptyEnds = 0;
    report(event);
    segment(); // Synchronous start preserves the user's microphone gesture.
  }
  const resumable = (context) =>
    armed &&
    !running &&
    !sending &&
    eligible(context) &&
    context.canStart &&
    context.available;
  function wake() {
    if (!resumable(getContext())) return;
    cancel(wakeTimer);
    const token = epoch;
    wakeTimer = later(() => {
      const context = getContext();
      if (token === epoch && resumable(context)) begin(context, "resume");
    }, WAKE_DELAY_MS);
  }
  function start() {
    if (running) return;
    const context = getContext();
    if (!eligible(context) || !context.canStart || sending) {
      report("start-rejected", {
        reason: context.blockedReason || "not-ready",
      });
      state({
        phase: "stopped",
        message: "目前不能收音；請回到可操作的計分頁後手動開始。",
      });
      return;
    }
    armed = true;
    begin(context, "start-requested");
  }
  function segment() {
    const context = getContext();
    if (!running) return;
    if (context.scope !== scope || !eligible(context))
      return suspend("context-changed");
    if (!context.canStart || sending) {
      // The previous command (or an animation) is still busy: wait instead of stopping.
      busySince ??= now();
      if (now() - busySince >= BUSY_WAIT_MS) return suspend("busy-timeout");
      const waitToken = epoch;
      later(() => {
        if (waitToken === epoch && running) segment();
      }, BUSY_POLL_MS);
      return;
    }
    busySince = null;
    const token = epoch,
      number = ++segmentNumber,
      started = now();
    let rec,
      decided = false,
      meaningful = false,
      finishing = false;
    let stableTimer,
      deadline,
      watchdog,
      stableText = "";
    let invalidReason = null;
    invalidateActive = (reason) => {
      if (!invalidReason)
        report("segment-invalidated", { segment: number, reason });
      invalidReason ||= reason;
    };
    const cleanup = () => {
      [stableTimer, deadline, watchdog].forEach(cancel);
    };
    const current = () =>
      running &&
      token === epoch &&
      rec === recognizer &&
      getContext().scope === scope &&
      eligible(getContext());
    const finish = (reason) => {
      if (!current() || finishing) return;
      finishing = true;
      cancel(stableTimer);
      report("request-final", { segment: number, reason });
      try {
        rec.stop();
      } catch (e) {
        stop("stop-error");
        state({ phase: "error", message: "語音停止失敗，請手動重新開始。" });
        return;
      }
      if (current())
        watchdog = later(() => {
          if (!current()) return;
          stop("end-timeout");
          state({
            phase: "error",
            message: "語音服務沒有結束回應，已停止；請手動重新開始。",
          });
        }, 2000);
    };
    try {
      rec = createRecognition();
      recognizer = rec;
      rec.lang = "zh-TW";
      rec.continuous = false;
      rec.interimResults = true;
      rec.maxAlternatives = 1;
      rec.onstart = () => {
        if (!current()) return;
        report("listening", { segment: number });
        state({ phase: "listening" });
      };
      rec.onspeechend = () => finish("speechend");
      rec.onresult = (event) => {
        if (!current()) {
          report("rejected", { reason: "stale-session", segment: number });
          return;
        }
        const results = Array.from(event.results);
        const raw = results.map((r) => r[0]?.transcript || "").join(" ");
        const final = results.length > 0 && results.every((r) => r.isFinal);
        const { normalized, command } = parseCommand(raw);
        report("recognition", {
          segment: number,
          raw,
          final,
          normalized,
          command: command?.key || null,
        });
        const observed = getContext();
        if (!observed.available || sending)
          invalidateActive?.(observed.blockedReason || "command-inflight");
        if (!final) {
          if (normalized !== stableText) {
            cancel(stableTimer);
            stableText = normalized;
            if (command)
              stableTimer = later(
                () => finish("stable-complete-command"),
                1000,
              );
          }
          return;
        }
        meaningful = true;
        cancel(stableTimer);
        if (decided) {
          report("deduplicated", {
            reason: "segment-already-final",
            segment: number,
          });
          return;
        }
        decided = true;
        if (!command) {
          report("rejected", {
            reason: "not-one-complete-command",
            segment: number,
          });
          finish("final");
          return;
        }
        const live = getContext();
        let reason =
          invalidReason ||
          (!live.available
            ? live.blockedReason || "not-writable"
            : sending
              ? "command-inflight"
              : null);
        if (command.action === "undo" && !live.canUndo)
          reason = "nothing-to-undo";
        if (reason) {
          report("rejected", { reason, command: command.key });
          finish("final");
          return;
        }
        const previous = recent.get(command.key);
        if (previous !== undefined && now() - previous < 1800) {
          report("deduplicated", {
            reason: "same-command-within-1800ms",
            command: command.key,
          });
          finish("final");
          return;
        }
        recent.set(command.key, now());
        sending = true;
        report("accepted", { command: command.key });
        report("send", { command: command.key });
        state({ phase: "sending", message: "口令已辨識，等待計分確認…" });
        // No await occurs between the live guards and room.act.
        let request;
        try {
          request = send(command);
        } catch (e) {
          request = Promise.reject(e);
        }
        Promise.resolve(request)
          .then((result) => {
            const stillSame =
              token === epoch &&
              running &&
              getContext().scope === scope &&
              eligible(getContext());
            if (!result) {
              report("failed", {
                scope: live.scope,
                command: command.key,
                reason: "command-not-confirmed",
              });
              if (stillSame)
                state({
                  phase: "listening",
                  message:
                    "操作未確認成功；請查看計分板訊息，不會自動補送新口令。",
                });
              return;
            }
            if (
              result.roomId !== live.roomId ||
              result.matchId !== live.matchId
            ) {
              report("failed", {
                scope: live.scope,
                command: command.key,
                reason: "response-scope-mismatch",
              });
              return;
            }
            report("success", {
              scope: live.scope,
              command: command.key,
              version: result.version,
              score: [result.teamAScore, result.teamBScore],
              feedbackSuppressed: !stillSame,
            });
            if (stillSame)
              state({
                phase: "listening",
                message: `${command.action === "undo" ? "已撤回最後一分。" : "已加分。"}紅方 ${result.teamAScore}，藍方 ${result.teamBScore}`,
              });
          })
          .catch((e) => {
            report("failed", {
              scope: live.scope,
              command: command.key,
              reason: "command-error",
              detail: e.message,
            });
            if (token === epoch && running)
              state({
                phase: "listening",
                message: "計分操作失敗，請查看畫面；沒有宣告成功。",
              });
          })
          .finally(() => {
            sending = false;
          });
        finish("final");
      };
      rec.onerror = (event) => {
        if (!current()) return;
        report("recognition-error", {
          segment: number,
          error: event.error,
          detail: event.message || "",
        });
        if (event.error === "no-speech") {
          finish("no-speech");
          return;
        }
        stop(event.error || "recognition-error");
        state({
          phase: "error",
          message:
            ERROR_MESSAGES[event.error] ||
            "語音服務已停止，請手動重新開始；手動計分仍可使用。",
        });
      };
      rec.onend = () => {
        if (!current()) return;
        cleanup();
        rec.onstart =
          rec.onresult =
          rec.onend =
          rec.onerror =
          rec.onspeechend =
            null;
        recognizer = null;
        invalidateActive = null;
        const elapsed = now() - started;
        rapidEmptyEnds = !meaningful && elapsed < 1200 ? rapidEmptyEnds + 1 : 0;
        report("recognition-end", {
          segment: number,
          elapsed,
          meaningful,
          rapidEmptyEnds,
        });
        if (rapidEmptyEnds >= 3) {
          stop("rapid-empty-ends");
          state({
            phase: "error",
            message:
              "語音服務連續過快中斷，已停止。請確認麥克風或改用獨立 Safari。",
          });
          return;
        }
        state({ phase: "restarting" });
        later(() => {
          if (token !== epoch || !running) return;
          report("restart", { previousSegment: number });
          segment();
        }, 500);
      };
      state({ phase: "starting" });
      report("recognition-start", { segment: number });
      rec.start();
      if (current())
        deadline = later(() => finish("segment-8000ms-limit"), 8000);
    } catch (e) {
      cleanup();
      report("recognition-error", { error: e.name, detail: e.message });
      stop("start-error");
      state({
        phase: "error",
        message: "無法啟動語音服務，請檢查權限及瀏覽器；手動計分不受影響。",
      });
    }
  }
  return {
    start,
    stop,
    suspend,
    wake,
    invalidate: (reason) => invalidateActive?.(reason),
    dispose: () => stop("unmount"),
  };
}
module.exports = { createVoiceController };
